"""CliffCS₂ on two wires: Knuth–Bendix completion in the group generated by H₀, S₀, S₁, CS
and ω (order 18432), until the block relations that the search does not reach are provable."""
import sys, time
import numpy as np
import cscliff as C
from cscliff import L
from cskb import KB

w, S1, CS, S0, H0 = L('w'), L('S', 1), L('CS'), L('S'), L('H')
LET = [w, S1, CS, S0, H0]

def op(time_word): return tuple(reversed(time_word))
def rep(x, k): return [x] * k

BASE = [
    ('w8', (w,) * 8, ()), ('H2', (H0, H0), ()), ('S04', (S0,) * 4, ()), ('S14', (S1,) * 4, ()),
    ('CS4', (CS,) * 4, ()),
    ('wS1', (w, S1), (S1, w)), ('wCS', (w, CS), (CS, w)), ('wS0', (w, S0), (S0, w)), ('wH0', (w, H0), (H0, w)),
    ('S1S0', (S1, S0), (S0, S1)), ('S1H0', (S1, H0), (H0, S1)),
    ('S1CS', (S1, CS), (CS, S1)), ('S0CS', (S0, CS), (CS, S0)),
    ('E', op([H0, S0, H0]), op([w, S0, S0, S0, H0, S0, S0, S0])),
    ('CE^', op([S0, H0, CS, H0, CS]), op([CS, H0, CS, H0, S0])),
    ('XCS^', op([H0, S0, S0, H0, CS]), op([CS, CS, CS, H0, S0, S0, H0, S1])),
]
CK = op([S1, S1, S1, CS, H0, CS, H0, CS])
T2 = op([H0, CS, CS, H0])
T0 = op([H0, S0, S0, CS, CS, H0])
Y = op([w] * 6 + [S1, CS, CS, CS, S0, H0, CS, CS, CS, S0, H0, CS, CS, CS, S0])
TARGETS = {
    'CK2': (CK + CK, (S1, S1, S1)),
    'R15': (CK + (CS, CS), T2 + CK),
    'R16': (CK + (CS,) * 3, (CS,) + CK + (CS,) + CK),
    'St0ck': (T0 + CK, CK + T0),
    'KK0y': (Y + CK, (H0,) + (w,) * 7),
}

def opmat(word):
    return C.mat(2, list(reversed(word)))

if __name__ == '__main__':
    for nm, l, r in BASE: assert np.allclose(opmat(l), opmat(r)), nm
    for nm, (l, r) in TARGETS.items(): assert np.allclose(opmat(l), opmat(r)), nm
    X1 = [L('H', 1), L('S', 1), L('S', 1), L('H', 1)]
    assert np.allclose(opmat(Y), C.mat(2, X1 + list(reversed(CK)) + X1))
    print('numerics ok')
    order = sys.argv[1] if len(sys.argv) > 1 else 'w S1 CS S0 H0'
    names = {'w': w, 'S1': S1, 'CS': CS, 'S0': S0, 'H0': H0}
    kb = KB([names[x] for x in order.split()], BASE)
    t = time.time()
    ok = kb.run(targets=list(TARGETS.values()), maxrules=20000, report=500)
    print('done', ok, len(kb.index), 'rules, %.0fs' % (time.time() - t))
    for nm, (l, r) in TARGETS.items():
        print(nm, kb.provable(l, r))

def needed(kb, steps_list):
    seen = set(); stack = []
    for st in steps_list:
        for (p, rid, rev) in st: stack.append(rid)
    while stack:
        r = stack.pop()
        if r in seen: continue
        seen.add(r)
        pr = kb.rules[r][2]
        if pr[0] != 'base':
            for (p, rid, rev) in pr: stack.append(rid)
    return seen

def analyse(kb):
    pfs = {nm: kb.proof_of(l, r) for nm, (l, r) in TARGETS.items()}
    for nm, st in pfs.items(): print(nm, len(st), 'steps')
    nd = needed(kb, pfs.values())
    der = [r for r in nd if kb.rules[r][2][0] != 'base']
    print(len(nd), 'rules needed,', len(der), 'derived, total steps',
          sum(len(kb.rules[r][2]) for r in der), 'max', max(len(kb.rules[r][2]) for r in der),
          'max lhs', max(len(kb.rules[r][0]) for r in nd))
    for r in der: assert kb.check(r)

if __name__ == '__main__':
    analyse(kb)
